export default function DeliveryDetails() {
    const { id } = useParams<{ id: string }>();
    const [delivery, setDelivery] = useState<Delivery | null>(null);
    const [driverId, setDriverId] = useState("");
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState("");
    const navigate = useNavigate();
  
    // ✅ Handle missing ID gracefully
    if (!id) {
      return (
        <div style={{ padding: "20px" }}>
          ❗ No delivery ID provided in URL.
          <br />
          <button onClick={() => navigate("/")} style={{ marginTop: "10px" }}>
            Go to Dashboard
          </button>
        </div>
      );
    }
  
    useEffect(() => {
      axios
        .get(`${API_BASE_URL}/api/delivery/get/${id}`)
        .then((res) => {
          setDelivery(res.data[0]);
          setLoading(false);
        })
        .catch((err) => {
          console.error("Error fetching delivery details:", err);
          setError("Failed to fetch delivery details");
          setLoading(false);
        });
    }, [id]);
  
    const handleAssignDriver = () => {
      if (!driverId) return alert("Please enter a Driver ID");
  
      axios
        .put(`${API_BASE_URL}/api/delivery/assign/${id}`, { driverId })
        .then(() => {
          alert("Driver assigned successfully!");
          setDelivery((prev) => (prev ? { ...prev, driverId } : prev));
        })
        .catch(() => {
          alert("Failed to assign driver");
        });
    };
  
    if (loading) return <div>Loading...</div>;
    if (error || !delivery) return <div>{error || "Delivery not found"}</div>;
  
    return (
      <div style={{ padding: "20px" }}>
        <h2>Delivery Details</h2>
        <p><strong>Customer ID:</strong> {delivery.customerId}</p>
        <p><strong>Status:</strong> {delivery.status}</p>
        <p><strong>Driver ID:</strong> {delivery.driverId || "Not assigned"}</p>
        <p><strong>Coordinates:</strong> {delivery.location?.lat}, {delivery.location?.lng}</p>
  
        <div style={{ marginTop: "20px" }}>
          <input
            type="text"
            placeholder="Enter Driver ID"
            value={driverId}
            onChange={(e) => setDriverId(e.target.value)}
            style={{ padding: "8px", marginRight: "10px" }}
          />
          <button onClick={handleAssignDriver} style={{ padding: "8px" }}>
            Assign Driver
          </button>
        </div>
  
        <div style={{ marginTop: "20px" }}>
          <button
            onClick={() => navigate(`/map?lat=${delivery.location.lat}&lng=${delivery.location.lng}`)}
            style={{ padding: "8px", marginRight: "10px" }}
          >
            View on Map
          </button>
  
          <button onClick={() => navigate(-1)} style={{ padding: "8px" }}>
            Back
          </button>
        </div>
      </div>
    );
  }
